        "code": "from collections import defaultdict, deque\n\nALLOWED_TOOLS = {\"fetch_metrics\", \"query_logs\", \"summarize\"}\n\ndef preflight_verify_plan(steps):\n    ids = {s[\"id\"] for s in steps}\n    for s in steps:\n        if s[\"tool\"] not in ALLOWED_TOOLS:\n            return {\"ok\": False, \"reason\": f\"disallowed tool {s['tool']}\"}\n        for d in s[\"deps\"]:\n            if d not in ids or d == s[\"id\"]:\n                return {\"ok\": False, \"reason\": f\"bad dep {d} on {s['id']}\"}\n    indeg = {s[\"id\"]: len(s[\"deps\"]) for s in steps}\n    children = defaultdict(list)\n    for s in steps:\n        for d in s[\"deps\"]:\n            children[d].append(s[\"id\"])\n    q = deque(k for k, v in indeg.items() if v == 0)\n    seen = 0\n    while q:\n        cur = q.popleft()\n        seen += 1\n        for nxt in children[cur]:\n            indeg[nxt] -= 1\n            if indeg[nxt] == 0:\n                q.append(nxt)\n    return {\"ok\": seen == len(steps), \"reason\": \"OK\" if seen == len(steps) else \"CYCLE_DETECTED\"}\n\nprint(preflight_verify_plan([{\"id\": \"1\", \"tool\": \"fetch_metrics\", \"deps\": []}, {\"id\": \"2\", \"tool\": \"summarize\", \"deps\": [\"1\"]}]))\nprint(preflight_verify_plan([{\"id\": \"1\", \"tool\": \"exec_shell\", \"deps\": []}]))",
