        "code": "class BillingLedger:\n    def __init__(self, balance_usd):\n        self.balance = balance_usd\n        self.holds = {}\n        self.settled = set()\n\n    def reserve(self, req_id, est_usd):\n        if req_id in self.holds or req_id in self.settled:\n            return {\"ok\": True, \"idempotent_replay\": True, \"balance\": round(self.balance, 4)}\n        if self.balance < est_usd:\n            return {\"ok\": False, \"error\": \"INSUFFICIENT_QUOTA\", \"balance\": round(self.balance, 4)}\n        self.balance -= est_usd\n        self.holds[req_id] = est_usd\n        return {\"ok\": True, \"idempotent_replay\": False, \"balance\": round(self.balance, 4)}\n\n    def settle(self, req_id, actual_usd):\n        if req_id in self.settled:\n            return {\"ok\": True, \"idempotent_replay\": True, \"balance\": round(self.balance, 4)}\n        reserved = self.holds.pop(req_id, actual_usd)\n        self.balance += (reserved - actual_usd)\n        self.settled.add(req_id)\n        return {\"ok\": True, \"refund\": round(reserved - actual_usd, 4), \"balance\": round(self.balance, 4)}\n\nbl = BillingLedger(1.00)\nprint(\"r1     :\", bl.reserve(\"req_1\", 0.40))\nprint(\"replay :\", bl.reserve(\"req_1\", 0.40))\nprint(\"settle :\", bl.settle(\"req_1\", 0.15))",
